  it('wraps an undefined rejection in an Error with cause for onError while rethrowing undefined', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(undefined), promptBuilder, undefined, {
      hooks,
    });
    const outcome = await orchestrator.processMessage(createSession('hello')).then(
      () => ({rejected: false, reason: 'resolved' as unknown}),
      (err: unknown) => ({rejected: true, reason: err})
    );

    expect({
      outcome,
      isError: receivedError instanceof Error,
      message: receivedError?.message,
      cause: receivedError?.cause,
    }).toEqual({
      outcome: {rejected: true, reason: undefined},
      isError: true,
      message: 'undefined',
      cause: undefined,
    });
  });
